package com.example

import com.example.ExamQuestionHelper.QSpec

internal object EnglishLiveExamPrepConjBank1 {
  private const val T = "Prepositions & Phrasal Verbs"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("The G.C.E. O/L examination begins ___ Monday morning.", "on", "at", "in", "by", "Days of the week always take the preposition 'on'."),
    q("Our school prize giving will be held ___ the 15th of October.", "on", "at", "in", "during", "Specific calendar dates take 'on'."),
    q("The morning assembly starts promptly ___ 7:30 a.m.", "at", "on", "in", "since", "Exact clock times take the preposition 'at'."),
    q("Sri Lanka celebrates Independence Day ___ February every year.", "in", "on", "at", "by", "Months without a specific date take 'in'."),
    q("The ancient palace at Sigiriya was built ___ the 5th century.", "in", "on", "at", "for", "Centuries and historical periods take 'in'."),
    q("She has been waiting at the bus stand ___ eight o'clock.", "since", "for", "from", "at", "'Since' marks a specific starting point in time."),
    q("My uncle has worked in Kandy ___ fifteen years.", "for", "since", "from", "during", "'For' marks a total duration of time."),
    q("The express train arrived ___ Colombo Fort station on schedule.", "at", "in", "on", "to", "Specific points or stations take 'arrived at'."),
    q("When did the tourists arrive ___ Sri Lanka?", "in", "at", "to", "on", "Countries and large cities take 'arrive in' (never 'arrive to')."),
    q("Please submit your project report ___ Friday at the latest.", "by", "until", "since", "during", "'By' indicates a final deadline ('not later than')."),
    q("Wait in the library ___ the heavy rain stops.", "until", "by", "during", "since", "'Until' indicates continuing up to a point in time."),
    q("Nobody is allowed to whisper ___ the examination.", "during", "while", "since", "until", "'During' precedes a noun phrase ('the examination')."),
    q("She is very good ___ solving difficult algebra problems.", "at", "in", "on", "with", "Skills and subjects pair with 'good at'."),
    q("He is quite keen ___ learning astronomical photography.", "on", "at", "for", "with", "Fixed adjective collocation: 'keen on'."),
    q("All students must abide ___ the school rules at all times.", "by", "with", "to", "for", "Fixed collocation: 'abide by' (follow rules)."),
    q("The Sri Lankan team succeeded ___ winning the regional trophy.", "in", "on", "to", "for", "Fixed collocation: 'succeed in + V-ing'."),
    q("Please refrain ___ throwing plastic wrappers into the stream.", "from", "of", "off", "against", "Fixed collocation: 'refrain from + V-ing'."),
    q("Malini is senior ___ me by three academic years.", "to", "than", "from", "over", "Latin adjectives like 'senior', 'junior', 'prefer' take 'to'."),
    q("I prefer fresh wood-apple juice ___ fizzy soft drinks.", "to", "than", "from", "over", "'Prefer X to Y' takes 'to' (never 'than')."),
    q("We congratulated Tharindu ___ his national essay award.", "on", "for", "at", "about", "Fixed verb collocation: 'congratulate someone on something'."),
    q("This ancient temple is famous ___ its stone moonstone carvings.", "for", "of", "with", "about", "Fixed collocation: 'famous for'."),
    q("Are you interested ___ joining the school astronomy club?", "in", "on", "at", "with", "Fixed collocation: 'interested in'."),
    q("My grandmother is very fond ___ classical Sinhala folk songs.", "of", "in", "on", "with", "Fixed collocation: 'fond of'."),
    q("Little children are often afraid ___ loud thunderstorms.", "of", "from", "with", "by", "Fixed collocation: 'afraid of'."),
    q("Parents are always proud ___ their children's honest efforts.", "of", "for", "with", "on", "Fixed collocation: 'proud of'."),
    q("Do you agree ___ the proposal put forward by the prefects?", "with", "to by", "on", "for", "'Agree with' a person, opinion, or proposal (or 'agree to' a plan)."),
    q("She apologized ___ the teacher for coming late to class.", "to", "at", "with", "on", "'Apologize to someone for something'."),
    q("Listen carefully ___ the instructions before starting the paper.", "to", "at", "for", "on", "Fixed verb collocation: 'listen to'."),
    q("The wooden bridge was built ___ the wide Mahaweli River.", "across", "among", "between", "within", "'Across' shows movement or spanning from one bank to the other."),
    q("Share these twelve mangoes equally ___ the two brothers.", "between", "among", "across", "through", "'Between' is used for two persons or distinct items."),
    q("Distribute the prize books ___ all forty students in the hall.", "among", "between", "across", "beyond", "'Among' is used for three or more items/people as a group."),
    q("The frightened cat jumped ___ the low garden wall.", "over", "under", "between", "since", "'Over' indicates movement above and across an obstacle."),
    q("The train passed ___ a dark tunnel in the central hills.", "through", "across", "among", "above", "'Through' expresses movement inside an enclosed space or tunnel."),
    q("Students walked quietly ___ the shaded corridor.", "along", "across", "between", "against", "'Along' indicates following the length of a path or corridor."),
    q("Don't lean your wet umbrella ___ the newly painted wall.", "against", "across", "among", "over", "'Against' denotes resting in contact for support."),
    q("He dove bravely ___ the deep blue swimming pool.", "into", "in", "at", "by", "'Into' indicates movement from outside to inside."),
    q("She took her dictionary ___ of her canvas backpack.", "out", "into", "off", "over", "'Out of' indicates movement from inside to outside."),
    q("The helicopter hovered steadily ___ the flooded village.", "above", "between", "among", "into", "'Above' denotes a higher vertical position."),
    q("Keep the heavy steel trunk ___ the wooden bed.", "under", "above", "among", "through", "'Under' denotes directly beneath something."),
    q("His house stands right ___ the public library and the bank.", "between", "among", "through", "into", "Position bounded by two landmarks uses 'between'."),
    q("They walked slowly ___ the winding footpath up the hill.", "up", "into", "among", "since", "'Up' shows upward movement along a slope."),
    q("Who is responsible ___ locking the computer lab after school?", "for", "of", "with", "to", "Fixed collocation: 'responsible for'."),
    q("The patient is slowly recovering ___ a severe bout of fever.", "from", "of", "with", "by", "Fixed collocation: 'recover from'."),
    q("Human beings depend ___ clean water and fresh air for survival.", "on", "in", "at", "of", "Fixed collocation: 'depend on'."),
    q("Don't laugh ___ others when they make small pronunciation errors.", "at", "on", "with", "for", "Fixed collocation: 'laugh at' (mock)."),
    q("She resembles her mother; everyone says she takes ___ her.", "after", "over", "up", "in", "Phrasal verb 'take after' means resemble an older relative."),
    q("The fire brigade arrived quickly and put ___ the forest blaze.", "out", "off", "away", "up", "Phrasal verb 'put out' means extinguish a fire."),
    q("The inter-school match was put ___ until Friday due to rain.", "off", "out", "away", "down", "Phrasal verb 'put off' means postpone."),
    q("Never put ___ until tomorrow what you can finish today.", "off", "out", "up", "in", "'Put off' means delay or postpone."),
    q("He couldn't put ___ with the noisy traffic outside his window.", "up", "off", "out", "down", "'Put up with' means tolerate patiently."),
    q("Do not look down ___ people who do humble manual work.", "on", "into", "for", "after", "'Look down on' means despise or treat as inferior."),
    q("Grandmother always looks ___ the little baby while parents work.", "after", "for", "at", "up", "'Look after' means take care of."),
    q("If you don't know a word's meaning, look it ___ in a dictionary.", "up", "after", "down", "into", "'Look up' means search for information in a reference book."),
    q("I am looking ___ my missing blue pen everywhere in the room.", "for", "after", "up", "into", "'Look for' means search for something lost."),
    q("The police promised to look ___ the mysterious theft thoroughly.", "into", "up", "after", "for", "'Look into' means investigate."),
    q("Students are looking forward ___ the educational excursion.", "to", "for", "at", "on", "'Look forward to' anticipates joyfully (followed by noun/V-ing)."),
    q("Don't give ___ easily when a math problem seems tough at first.", "up", "in", "out", "away", "'Give up' means stop trying or quit."),
    q("The chief guest gave ___ the merit certificates on stage.", "away", "up", "in", "off", "'Give away' means distribute prizes or donate."),
    q("The old car broke ___ halfway up the steep Kadugannawa pass.", "down", "out", "into", "up", "'Break down' means stop functioning mechanically."),
    q("A dangerous fire broke ___ inside the textile factory at midnight.", "out", "down", "in", "up", "'Break out' means start suddenly (fire, war, epidemic)."),
    q("Thieves broke ___ the empty jewellery shop during the storm.", "into", "out", "down", "off", "'Break into' means enter a building illegally by force."),
    q("The committee decided to carry ___ the planned tree planting.", "out", "in", "off", "up", "'Carry out' means execute or implement a plan/order."),
    q("Even after the bell rang, he carried ___ reading silently.", "on", "out", "away", "off", "'Carry on' means continue doing something."),
    q("We have run ___ of white chalk in the classroom cupboard.", "out", "into", "over", "away", "'Run out of' means exhaust the supply of something."),
    q("I unexpectedly ran ___ my primary school friend at the bookshop.", "into", "out", "off", "over", "'Run into' means meet someone by chance."),
    q("Always switch ___ the fans before leaving the empty classroom.", "off", "on", "out", "away", "'Switch off' means turn off electrical appliances."),
    q("Please turn ___ the radio volume; the baby is sleeping.", "down", "up", "off out", "into", "'Turn down' lowers volume (or rejects an offer)."),
    q("He had to turn ___ the invitation because he had an exam.", "down", "on", "out", "up", "'Turn down' also means decline or refuse an offer."),
    q("Over three hundred parents turned ___ for the annual meeting.", "up", "down", "off", "out into", "'Turn up' means arrive or appear."),
    q("It took my grandfather weeks to get ___ his severe flu.", "over", "out", "away", "into", "'Get over' means recover from an illness or setback."),
    q("The two brothers get ___ very well and never quarrel.", "along", "over", "away", "down", "'Get along' means have a harmonious relationship."),
    q("Please fill ___ this registration form in black ink.", "in", "over", "up off", "away", "'Fill in' (or 'fill out') means complete a form."),
    q("The plane took ___ smoothly despite the strong coastal wind.", "off", "on", "up", "away", "'Take off' means leave the ground (aircraft) or remove clothing."),
    q("Please take ___ your muddy shoes before entering the shrine.", "off", "out", "up", "over", "'Take off' means remove shoes/clothing."),
    q("Nimali decided to take ___ badminton as a healthy evening hobby.", "up", "off", "after", "out", "'Take up' means begin a new hobby or activity."),
    q("The captain called ___ the cricket match because of flooded pitches.", "off", "out", "in", "up", "'Call off' means cancel an event."),
    q("Let's call ___ Aunt Mala on our way back from Kurunegala.", "on", "off", "up", "out", "'Call on' means pay a brief visit to someone."),
    q("The old school building was pulled ___ to make way for a lab.", "down", "up", "out", "off", "'Pull down' means demolish a building."),
    q("She came ___ a rare old coin while digging in the garden.", "across", "into", "up", "off", "'Come across' means find or meet by chance."),
    q("When will the Grade 11 science magazine come ___?", "out", "off", "up", "over", "'Come out' means be published or released."),
    q("Try to cut ___ on sugary snacks to keep your teeth healthy.", "down", "off", "out", "up", "'Cut down on' means reduce consumption."),
    q("Make sure you hand ___ your essay before four o'clock.", "in", "out", "over", "off", "'Hand in' means submit work to a teacher/authority."),
    q("The prefects handed ___ the printed notices at the assembly.", "out", "in", "off", "up", "'Hand out' means distribute items to a group."),
    q("The teacher pointed ___ two spelling errors in my paragraph.", "out", "in", "off", "up", "'Point out' means draw attention to a specific detail."),
    q("Always keep ___ from deep water unless a lifeguard is present.", "away", "up", "on", "in", "'Keep away from' means stay at a safe distance."),
    q("Students must keep ___ the hard work right up to exam day.", "up", "away", "off", "out", "'Keep up' means maintain an effort or pace."),
    q("Can you work ___ the total cost without using a calculator?", "out", "up", "in", "off", "'Work out' means calculate or solve a problem."),
    q("She set ___ early at five to avoid heavy morning traffic.", "off", "up", "in", "down", "'Set off' means begin a journey."),
    q("The youth club set ___ a free book stall at the village fair.", "up", "off", "out", "down", "'Set up' means establish or organize something."),
    q("You can rely ___ Amaya to keep her promise every time.", "on", "in", "at", "for", "Fixed collocation: 'rely on'."),
    q("This textbook consists ___ twelve well-illustrated chapters.", "of", "with", "in", "from", "'Consist of' means be composed of (never 'consist with')."),
    q("Please translate this Sinhala proverb ___ clear English.", "into", "in", "to", "for", "Fixed collocation: 'translate into'."),
    q("He divided the chocolate cake ___ eight equal slices.", "into", "in", "on", "at", "Dividing something into parts takes 'into'."),
    q("The village tank is full ___ clear rainwater after the monsoon.", "of", "with", "by", "from", "Adjective 'full' pairs with 'of' ('filled' pairs with 'with')."),
    q("Our school is adjacent ___ the public children's park.", "to", "with", "from", "near", "Fixed collocation: 'adjacent to'."),
    q("Are you aware ___ the change in tomorrow's exam room?", "of", "about", "with", "for", "Fixed collocation: 'aware of'."),
    q("We are grateful ___ our teachers for their patient guidance.", "to", "for", "with", "at", "'Grateful to' a person, 'grateful for' something."),
    q("This plastic bottle is made ___ recycled materials.", "from", "by", "with", "at", "When raw material changes form completely, use 'made from' (e.g., paper from wood)."),
    q("This antique dining table is made ___ solid teak wood.", "of", "from", "by", "with", "When the original material remains visible and unchanged, use 'made of'.")
  )
}
